#include <stdio.h>

static int is_space(int c) {
    return c == ' ' || c == '\t' || c == '\n';
}

int main(void) {
    FILE *out = fopen("data.txt", "w");
    if (out == NULL) {
        perror("data.txt");
        return 1;
    }
    int c;
    while ((c = getchar()) != EOF) {
        fputc(c, out);
    }
    if (fclose(out) != 0) {
        perror("data.txt");
        return 1;
    }

    FILE *in = fopen("data.txt", "r");
    if (in == NULL) {
        perror("data.txt");
        return 1;
    }
    long lines = 0, words = 0, bytes = 0, current = 0, longest = 0;
    int inside = 0, last = '\n';
    while ((c = fgetc(in)) != EOF) {
        bytes++;
        if (c == '\n') {
            lines++;
            if (current > longest) {
                longest = current;
            }
            current = 0;
        } else {
            current++;
        }
        if (is_space(c)) {
            inside = 0;
        } else if (!inside) {
            inside = 1;
            words++;
        }
        last = c;
    }
    fclose(in);
    if (bytes > 0 && last != '\n') {
        lines++;
        if (current > longest) {
            longest = current;
        }
    }
    printf("строк %ld, слов %ld, байтов %ld, самая длинная %ld\n", lines, words, bytes, longest);
    return 0;
}

