    long long sum = 0;
    int max = 0;
    value = 0;
    while (!feof(in)) {
        fscanf(in, "%d", &value);
        if (count == 0 || value > max) {
            max = value;
        }
        sum += value;
        count++;
    }
    fclose(in);
    if (count == 0) {
        printf("чисел нет\n");
    } else {
        printf("чисел %d, сумма %lld, максимум %d\n", count, sum, max);
    }
    return 0;
}

